#!/usr/bin/env node
// Compiles the skill into portable files for agents other than Claude.
//
//   node build.mjs           write AGENTS.md, adapters/, agents/openai.yaml and export/<name>.md
//   node build.mjs --check   exit 1 if any generated file is stale
//
// Sources: SKILL.md, references/*.md, metadata.json. Never edit the outputs.
// The skill name is read from SKILL.md, so a rename needs no change here.

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { SKILL_DIR as root } from './lib.mjs'

const read = (p) => readFileSync(join(root, p), 'utf8')
const meta = JSON.parse(read('metadata.json'))
const skill = read('SKILL.md')
const front = skill.match(/^---\n([\s\S]*?)\n---\n/)
if (!front) throw new Error('SKILL.md has no frontmatter')
const body = skill.slice(front[0].length).trim()
const name = front[1].match(/^name:\s*(\S+)\s*$/m)?.[1]
const descRaw = front[1].match(/^description:\s*(".*")\s*$/m)?.[1]
if (!name || !descRaw) throw new Error('SKILL.md frontmatter needs name and a double-quoted description')
const description = JSON.parse(descRaw)
const title = body.match(/^# (.+)$/m)?.[1] ?? name

// Reference order is the order SKILL.md names them in, then any others.
const indexed = [...body.matchAll(/`references\/([a-z0-9-]+\.md)`/g)].map((m) => m[1])
const onDisk = readdirSync(join(root, 'references')).filter((f) => f.endsWith('.md')).sort()
const REFERENCES = [...new Set([...indexed, ...onDisk])].filter((f) => onDisk.includes(f))

// Push headings one level down, leaving fenced code alone.
const demote = (md) => md.split(/(```[\s\S]*?```)/).map((part, i) => (i % 2 ? part : part.replace(/^(#{1,5}) /gm, '#$1 '))).join('')
const banner = '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->'

const agents = [
  banner,
  '',
  body.replace(/^# .*$/m, `# ${name}\n\n**Version ${meta.version}** · ${meta.organization} · ${meta.date}\n\n${meta.abstract}`),
  '',
  '---',
  '',
  '# Reference material',
  '',
  "The sections below are the skill's `references/` files, included so this document works alone. Where the text above names `references/x.md`, read the section of that name below.",
  '',
  ...REFERENCES.map((f) => `<!-- references/${f} -->\n` + demote(read(`references/${f}`).trim()) + '\n'),
].join('\n')

const cursor = [
  '---',
  `description: ${JSON.stringify(description)}`,
  'globs: ["**/*.html", "**/*.astro", "**/robots.txt", "**/sitemap*.xml", "**/*seo*", "**/skills/' + name + '/**"]',
  'alwaysApply: false',
  '---',
  '',
  banner,
  '',
  body,
  '',
].join('\n')

const chatgpt = [
  banner,
  '',
  '# Instructions for a custom GPT or project',
  '',
  'Paste the block below into the instructions field. Upload `AGENTS.md` from this skill as a knowledge file.',
  '',
  '```',
  'You plan, audit and report on how Wugweb pages are found in search engines and',
  'AI answers, using the method in the uploaded file AGENTS.md. Read AGENTS.md',
  'before any task about keywords, search intent, a content brief, a title or',
  'description, schema, robots.txt, AI crawlers, rankings or Search Console.',
  '',
  'Always:',
  '- Use the part the task needs: plan before writing, audit after building,',
  '  report after launch.',
  '- Apply the fixed rules in AGENTS.md over any other advice.',
  '- Give computed totals first, then one line per finding with its severity,',
  '  its place and its check id.',
  '- Name the source and date of every number, or mark it unvalidated.',
  '- State what was not checked.',
  '- Do the one check the user asked for, then name the next most useful one.',
  '- If the page passes, say it passes and stop.',
  '',
  'Never:',
  '- Write or rewrite page copy, headings, titles or descriptions.',
  '- Propose HowTo, review stars, llms.txt, a keyword density, or FAQPage for questions the page does not show.',
  '- Invent a number, a finding, a ranking or a source.',
  '- Change a file, page or record yourself.',
  '',
  'If you can run code, run scripts/check-page.mjs on the page HTML and',
  'scripts/check-robots.mjs on robots.txt. If you cannot, apply the checks by',
  'reading the files the user shares and label the result a manual check.',
  '```',
  '',
].join('\n')

const openai = [
  '# Generated by scripts/build.mjs. Do not edit by hand.',
  '# Display settings for Codex and the ChatGPT desktop app. Other agents ignore this file.',
  'interface:',
  `  display_name: ${JSON.stringify(title)}`,
  '  short_description: "Plan, audit and report on search and AI answers"',
  '  default_prompt: "Audit this page for search and AI answers and give me the fix list."',
  'policy:',
  '  allow_implicit_invocation: true',
  '',
].join('\n')

// The single-file export: a short header, then AGENTS.md as it is.
const exported = [
  `# ${name} (single-file export, v${meta.version})`,
  '',
  'Built from the skill folder. Rebuild whenever the skill changes. Read the skill first, then the reference a part names.',
  '',
  agents,
].join('\n')

const outputs = {
  'AGENTS.md': agents,
  [`export/${name}.md`]: exported,
  [`adapters/cursor/${name}.mdc`]: cursor,
  'adapters/chatgpt/instructions.md': chatgpt,
  'agents/openai.yaml': openai,
}

const check = process.argv.includes('--check')
let stale = 0
for (const [path, content] of Object.entries(outputs)) {
  const full = join(root, path)
  const current = existsSync(full) ? readFileSync(full, 'utf8') : null
  if (check) {
    const ok = current === content
    console.log(`${ok ? 'fresh' : 'STALE'}  ${path}`)
    if (!ok) stale++
  } else {
    mkdirSync(dirname(full), { recursive: true })
    writeFileSync(full, content)
    console.log(`wrote  ${path}`)
  }
}
process.exit(stale ? 1 : 0)
